function mostFrequentEven(nums) {
  const count = new Map();
  for (const num of nums) {
    if (num % 2 === 0) {
      count.set(num, (count.get(num) ?? 0) + 1);
    }
  }

  let answer = -1;
  let bestCount = 0;
  for (const [num, freq] of count) {
    if (freq > bestCount || (freq === bestCount && num < answer)) {
      answer = num;
      bestCount = freq;
    }
  }
  return answer;
}

