function mostFrequentEven(nums) {
  const evens = [...new Set(nums.filter(v => v % 2 === 0))].sort((a, b) => a - b);
  let answer = -1;
  let most = 0;
  for (const value of evens) {
    let times = 0;
    for (const v of nums) if (v === value) times++;
    if (times > most) {
      most = times;
      answer = value;
    }
  }
  return answer;
}

