function generate(rand, size) {
  const n = size === 'large' ? 2000 : 1 + Math.floor(rand() * 10);
  const style = rand();
  const span = size === 'large' ? (style < 0.5 ? 60 : 100000) : (style < 0.5 ? 6 : 15);
  const onlyOdd = rand() < 0.15;
  const nums = Array.from({ length: n }, () => {
    const v = Math.floor(rand() * (span + 1));
    return onlyOdd ? (v % 2 === 0 ? (v === span ? v - 1 : v + 1) : v) : v;
  });
  return [nums];
}
